class Student {
    private int id;
    private String name;

    public void setData(int a, String b) {
        id = a;
        name = b;
    }

    public int getId() {
        return id;
    }

    public String getName() {
        return name;
    }
}

class Demo {
    public static void main(String[] args) {
        Student s = new Student();

        s.setData(10, "Ramesh");

        System.out.println(s.getId() + " " + s.getName());
    }
}

